"""In-depth mutation generator (Stirling numbers + combinatorial interpretation + cross-checked).

Deepens combinatorics.stirling_numbers: the problem asks for the number of ways to partition a set of `n` objects into `k` non-empty subsets, but with a twist — it requires the solver to interpret the problem combinatorially, such as counting ways to assign objects to bins or represent set partitions geometrically. This requires a deeper understanding of Stirling numbers and their interpretation, rather than just applying the formula.

To solve, given only `n` and `k`, the solver must:
  (1) Recognize the problem involves Stirling numbers of the second kind;
  (2) Interpret the combinatorial structure (e.g., set partitions, bin assignments);
  (3) Apply the Stirling number formula or a combinatorial identity (e.g., inclusion-exclusion) to compute the result;
  (4) Return the count.

Two independent answer paths are cross-checked at generation time:
  PATH A (insight): use the inclusion-exclusion formula to compute Stirling numbers.
  PATH B (brute): use recursive counting of set partitions.

Guards ensure the problem is non-degenerate and avoid small or guessable answers.
Problem text refrains from revealing the combinatorial interpretation or that Stirling numbers are involved.
"""

import random
import sympy

def generate(seed):
    rng = random.Random(seed)
    while True:
        n = rng.randint(2, 10)
        k = rng.randint(1, n)

        # Guard against small or trivial cases.
        if n < k:
            continue
        if n <= 2 or k <= 1:
            continue

        # --- PATH A: insight (inclusion-exclusion formula) ---
        def stirling_second_kind(n, k):
            if k == 0 or n == 0:
                return 0
            if k == n:
                return 1
            sum_val = 0
            for i in range(k + 1):
                sum_val += (-1) ** (k - i) * sympy.binomial(k, i) * i ** n
            return sum_val // sympy.factorial(k)

        answer_insight = stirling_second_kind(n, k)
        answer_insight = int(answer_insight)

        # --- PATH B: brute (recursive counting) ---
        def count_partitions(n, k):
            if k == 0 or n == 0:
                return 0
            if k == n:
                return 1
            return k * count_partitions(n - 1, k) + count_partitions(n - 1, k - 1)

        answer_brute = count_partitions(n, k)
        answer_brute = int(answer_brute)

        # --- CROSS-CHECK: inclusion-exclusion must equal recursive counting ---
        assert answer_insight == answer_brute, (
            f"count mismatch n={n} k={k}: "
            f"insight={answer_insight} brute={answer_brute}"
        )

        # Confirm the result is non-trivial and not guessable.
        if answer_insight <= 1:
            continue
        break

    problem = (
        f"How many ways can you partition a set of {n} distinct objects "
        f"into {k} non-empty subsets? State only the integer count."
    )
    return problem, str(sympy.Integer(answer_insight))

CONCEPT_REASON = "To solve, the solver must recognize that the problem involves partitioning a set of distinct objects into non-empty subsets and apply the inclusion-exclusion formula or recursive counting to compute the Stirling numbers of the second kind."
